insert into public.posts (kind, title, summary, category, source, published_on, url, position) values ('blog', '[KGU series 12] 가야대전 멀티골의 주인공! 경기대학교 서민준 선수 단독 인터뷰', '이번 제21회 1·2학년 대학축구연맹전 황가람기에서 경기대 축구부의 스코어보드를 가장 뜨겁게 달군 인물, 바로 1학년 서민준 선수입니다.', '인터뷰', '축구부 블로그', '2026-10-06', 'https://blog.naver.com/orangeturtles/224432818144', 0) on conflict (url) do nothing;
