insert into public.posts (kind, title, summary, category, source, published_on, url, position) values ('blog', '[KGU series 9] ''동시 득점왕'' 타이틀을 넘어 국가대표를 꿈꾸다, 김기완 선수', '2026년의 시작을 알리는 무대에서 경기대학교 축구부는 가장 날카로운 창을 발견했습니다.', '인터뷰', '축구부 블로그', '2026-03-21', 'https://blog.naver.com/orangeturtles/224224694941', 3) on conflict (url) do nothing;
insert into public.posts (kind, title, summary, category, source, published_on, url, position) values ('blog', '[KGU series 8] 2026시즌 경기대학교 축구부 캡틴, 갈정민 선수', '2026년 새 시즌을 앞둔 경기대학교 축구부에게 이번 동계 대회 새로운 리더십과 팀의 결속력을 다지는 중요한 변환점이었습니다.', '인터뷰', '축구부 블로그', '2026-03-16', 'https://blog.naver.com/orangeturtles/224217933083', 4) on conflict (url) do nothing;
